using AISmartLearning.API.Contracts;using AISmartLearning.API.Data;using AISmartLearning.API.Models;using AISmartLearning.API.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AISmartLearning.API.Controllers;
[ApiController][Authorize(Roles="Student,Teacher")][Route("api/conversations")] public sealed class ConversationsController(AppDbContext db,AiService ai,InteractionLogService logs):ControllerBase {
[HttpGet] public async Task<IActionResult> List(CancellationToken ct){var uid=InteractionLogService.UserId(User);var xs=await db.Conversations.Where(x=>x.UserId==uid).OrderByDescending(x=>x.StartedAt).Select(x=>new ConversationDto(x.ConversationId,x.Title,x.StartedAt,x.EndedAt,x.Status,x.Messages.Count)).ToListAsync(ct);return Ok(xs);}
[HttpPost] public async Task<IActionResult> Create(CreateConversationRequest r,CancellationToken ct){var uid=InteractionLogService.UserId(User);var title=string.IsNullOrWhiteSpace(r.Title)?"New conversation":r.Title.Trim();if(title.Length>200)title=title[..200];var c=new Conversation{UserId=uid,Title=title,StartedAt=DateTime.UtcNow};db.Conversations.Add(c);await db.SaveChangesAsync(ct);await logs.Write(uid,"ConversationCreated",$"Created conversation: {title}",c.ConversationId,ct);return Ok(new ConversationDto(c.ConversationId,c.Title,c.StartedAt,null,c.Status,0));}
[HttpGet("{id:int}/messages")] public async Task<IActionResult> Messages(int id,CancellationToken ct){var uid=InteractionLogService.UserId(User);if(!await db.Conversations.AnyAsync(x=>x.ConversationId==id&&x.UserId==uid,ct))return NotFound(new{message="Conversation not found."});return Ok(await db.ConversationMessages.Where(x=>x.ConversationId==id).OrderBy(x=>x.CreatedAt).Select(x=>new MessageDto(x.MessageId,x.SenderType,x.MessageText,x.CreatedAt)).ToListAsync(ct));}
[HttpPost("{id:int}/messages")] public async Task<IActionResult> Send(int id,SendMessageRequest r,CancellationToken ct){var uid=InteractionLogService.UserId(User);var text=r.Message?.Trim();if(string.IsNullOrWhiteSpace(text))return BadRequest(new{message="Message cannot be empty."});if(text.Length>8000)return BadRequest(new{message="Message must be 8,000 characters or fewer."});var c=await db.Conversations.Include(x=>x.User).ThenInclude(x=>x!.Role).SingleOrDefaultAsync(x=>x.ConversationId==id&&x.UserId==uid,ct);if(c is null)return NotFound(new{message="Conversation not found."});var um=new ConversationMessage{ConversationId=id,SenderType="User",MessageText=text,CreatedAt=DateTime.UtcNow};db.ConversationMessages.Add(um);await db.SaveChangesAsync(ct);var hist=await db.ConversationMessages.AsNoTracking().Where(x=>x.ConversationId==id&&x.MessageId!=um.MessageId).OrderBy(x=>x.CreatedAt).Select(x=>new{x.SenderType,x.MessageText}).ToListAsync(ct);try{var reply=await ai.Reply(c.User?.Role?.RoleName??"Student",text,hist.TakeLast(6).Select(x=>(x.SenderType,x.MessageText)).ToList(),ct);var am=new ConversationMessage{ConversationId=id,SenderType="AI",MessageText=reply,CreatedAt=DateTime.UtcNow};db.ConversationMessages.Add(am);await db.SaveChangesAsync(ct);await logs.Write(uid,"AIConversation",$"User message length={text.Length}; AI response length={reply.Length}",id,ct);return Ok(new{userMessage=new MessageDto(um.MessageId,um.SenderType,um.MessageText,um.CreatedAt),aiMessage=new MessageDto(am.MessageId,am.SenderType,am.MessageText,am.CreatedAt)});}catch(InvalidOperationException ex){await logs.Write(uid,"AIError",ex.Message,id,ct);return StatusCode(503,new{message=ex.Message});}catch(HttpRequestException ex){await logs.Write(uid,"AIError",ex.Message,id,ct);return StatusCode(502,new{message=ex.Message});}}
}